const rows = $input.all().map((i) => i.json).filter((r) => r && r.order_id);

const zona = 'Asia/Jakarta';
const ymd = (d) => d.toLocaleDateString('en-CA', { timeZone: zona });
const now = new Date();
const h3 = ymd(new Date(now.getTime() + 3 * 86400000));
const kemarin = ymd(new Date(now.getTime() - 86400000));

// Masa aktif per paket (TASKS P2.1). OTORITAS penegakannya ada di WP —
// mu-plugins/undangan-core/masa-aktif.php (kueri post_status=publish, idempoten,
// menyusul sendiri bila satu hari terlewat). Di sini nilainya HANYA dipakai untuk
// menghitung kapan mengirim peringatan; kalau kedua tempat ini drift, yang meleset
// cuma waktu peringatan, bukan kapan undangan benar-benar dinonaktifkan.
const MASA_AKTIF_HARI = { hemat: 7, favorit: 30, premium: 365 };
const HARI_PERINGATAN = 3;

const items = [];
for (const r of rows) {
  const wa = String(r.wa || '').replace(/\D/g, '');
  if (!wa) continue;
  const status = String(r.status || '').toUpperCase();
  const nama = String(r.nama || 'Kak').split(' ')[0];
  const mempelai = String(r.mempelai || '').trim();
  const tglAcara = String(r.tgl_acara || '').slice(0, 10);

  // Nudge belum isi data (T4.1 [+], template 3): hanya jendela 24–48 jam →
  // terkirim tepat SEKALI oleh cron harian, tanpa perlu kolom penanda.
  if (status === 'MENUNGGU_DATA') {
    const t = new Date(String(r.tgl_order || '').replace(' ', 'T') + ':00+07:00');
    const umurJam = (now - t) / 3600000;
    if (isFinite(umurJam) && umurJam >= 24 && umurJam < 48) {
      const paket = String(r.paket || '').toLowerCase();
      const link = `${$env.WP_URL}/isi-data/?order=${r.order_id}&key=${r.token}${paket ? `&paket=${paket}` : ''}`;
      items.push({ json: { wa, label: `nudge #${r.order_id}`, teks: `Halo ${nama} 👋\n\nPesanan *#${r.order_id}* kamu sudah aktif, tapi data undangannya belum diisi.\n\nIsi sekarang (±10 menit), undangannya langsung jadi:\n${link}\n\nAda kendala saat mengisi? Balas pesan ini, kami bantu sampai selesai.\n— hariH` } });
    }
  }

  if (status !== 'SUDAH_JADI') continue;

  // Reminder H-3 (template 4)
  if (tglAcara === h3 && r.link_undangan) {
    const utk = mempelai ? `hari bahagia ${mempelai}` : 'hari bahagiamu';
    items.push({ json: { wa, label: `h-3 #${r.order_id}`, teks: `Halo ${nama}! Tinggal *3 hari* menuju ${utk} 🎉\n\nYuk cek undangannya sekali lagi — pastikan tanggal, waktu, lokasi, dan nama sudah benar:\n${r.link_undangan}\n\nAda yang perlu dikoreksi? Hubungi kami hari ini juga supaya sempat direvisi.\n\nSemoga persiapannya lancar! 🤍\n— hariH` } });
  }

  // Peringatan sebelum masa aktif berakhir (P2.1) — supaya halaman tidak
  // mati mendadak di tangan customer. Dikirim tepat sekali: hanya saat hari ini
  // persis H_PERINGATAN hari sebelum tanggal kedaluwarsa.
  if (tglAcara && r.link_undangan) {
    const hariAktif = MASA_AKTIF_HARI[String(r.paket || '').toLowerCase()] ?? MASA_AKTIF_HARI.hemat;
    const akhir = new Date(`${tglAcara}T23:59:59+07:00`);
    if (!isNaN(akhir)) {
      const kedaluwarsa = ymd(new Date(akhir.getTime() + hariAktif * 86400000));
      const peringatanPada = ymd(new Date(akhir.getTime() + (hariAktif - HARI_PERINGATAN) * 86400000));
      if (ymd(now) === peringatanPada) {
        items.push({ json: { wa, label: `masa-aktif #${r.order_id}`, teks: `Halo ${nama} 🤍\n\nMasa aktif halaman undangan kalian berakhir *${kedaluwarsa}* (sesuai paket ${r.paket || 'hemat'}). Setelah itu link-nya tidak bisa dibuka lagi oleh tamu.\n\n${r.link_undangan}\n\n📌 Sebelum itu, sempatkan simpan yang ingin dikenang: screenshot halamannya dan daftar ucapan dari tamu.\n\nIngin diperpanjang? Balas pesan ini, kami bantu.\n— hariH` } });
      }
    }
  }

  // Selamat H+1 + testimoni (template 5)
  if (tglAcara === kemarin) {
    const sapaan = mempelai ? `, ${mempelai}` : '';
    items.push({ json: { wa, label: `h+1 #${r.order_id}`, teks: `Selamat menempuh hidup baru${sapaan}! 🎊\n\nTerima kasih sudah mempercayakan undangan digital kalian ke hariH — semoga menjadi keluarga yang bahagia.\n\n🙏 Kalau berkenan, balas pesan ini dengan kesan singkatmu memakai hariH. Testimonimu sangat berarti untuk kami.\n\n💝 Punya kerabat yang akan menikah? Bagikan hariH ke mereka: https://harih.id/\n\n— hariH` } });
  }
}

// Kosong → tidak ada item → node kirim tidak berjalan (normal, bukan error)
return items;
